{"command": "python3 - << 'EOF'
import subprocess, json, base64, numpy as np, wave

def ft2(tool, args):
    res = subprocess.run(['ft2', 'call', tool, json.dumps(args)], capture_output=True, text=True)
    if res.returncode != 0:
        print("ERR:", tool, res.stdout, res.stderr)
    return json.loads(res.stdout)

print("module_new:", ft2('module_new', {'channels': 8, 'name': 'TEST'}))

# Create a 1-period sine wave at C-4? Wait: in FT2, sample rate for C-4 (note 49? or 48?) is 8363 Hz by default!
# Let's test sample_create_from_pcm with 64 samples of sine wave, loop 0..64, flags=1 (forward loop) or flags=17 (16-bit + forward loop)?
# Wait! Let's test what sample_create_from_pcm sets and what module_save produces!
t = np.arange(64) / 64.0
pcm = (np.sin(2 * np.pi * t) * 30000).astype('<i2').tobytes()
b64 = base64.b64encode(pcm).decode('ascii')

print("sample_create:", ft2('sample_create_from_pcm', {
    'instrument': 1, 'sample': 0, 'pcm': b64, 'encoding': 'int16', 'name': 'sine64'
}))
print("sample_set:", ft2('sample_set', {
    'instrument': 1, 'sample': 0, 'volume': 64, 'panning': 128,
    'finetune': 0, 'relative_note': 0, 'loop_start': 0, 'loop_length': 64, 'flags': 1
}))
print("set_cell C-4:", ft2('pattern_set_cell', {
    'pattern': 0, 'row': 0, 'channel': 0, 'note': 'C-4', 'instrument': 1
}))
print("get_cell 0:", ft2('pattern_get_cell', {'pattern': 0, 'row': 0, 'channel': 0}))
print("save xm:", ft2('module_save', {'path': '/tmp/probe/test.xm', 'format': 'xm'}))
print("render wav:", ft2('module_render', {'path': '/tmp/probe/test.wav', 'rate': 44100, 'bits': 16, 'loops': 1}))
EOF"}

