{"command": "python3 - << 'EOF'
import subprocess, json, base64, numpy as np, wave

def ft2(tool, args):
    return json.loads(subprocess.run(['ft2', 'call', tool, json.dumps(args)], capture_output=True, text=True).stdout)

ft2('module_new', {'channels': 4, 'name': 'AMPTEST'})
t = np.arange(128) / 128.0
sine = (np.sin(2 * np.pi * t) * 16000).astype('<i2').tobytes()
ft2('sample_create_from_pcm', {'instrument': 1, 'sample': 0, 'pcm': base64.b64encode(sine).decode(), 'encoding': 'int16', 'name': 's'})
ft2('sample_set', {'instrument': 1, 'sample': 0, 'volume': 64, 'panning': 128, 'relative_note': 24, 'loop_start': 0, 'loop_length': 128, 'flags': 17})
ft2('pattern_set_cell', {'pattern': 0, 'row': 0, 'channel': 0, 'note': 'C-4', 'instrument': 1, 'volume': 0x50})

for amp_arg in [None, 1, 4, 10, 12, 16, 20, 32]:
    args = {'path': f'/tmp/probe/amp2_{amp_arg}.wav', 'rate': 44100, 'bits': 16}
    if amp_arg is not None:
        args['amp'] = amp_arg
    ft2('module_render', args)
    with wave.open(args['path'], 'rb') as w:
        audio = np.frombuffer(w.readframes(w.getnframes()), dtype='<i2').reshape(-1, 2)
    print(f"amp={str(amp_arg):4s} -> peak={np.max(np.abs(audio))}, rms={np.sqrt(np.mean(audio.astype(float)**2)):.1f}")
EOF"}

