    g = PatternGrid(n_pats=15, rows=128)

    PAT_CHORDS = {
        0:  ['Cm', 'Ab', 'Fm7', 'G7'],
        1:  ['Cm', 'Ab', 'Eb', 'Bb'],
        2:  ['Cm', 'Ab', 'Fm7', 'G7'],
        3:  ['Cm', 'Ab', 'Eb', 'Bb'],
