    'Abmaj7': ('Ab1', 'Ab3', 0xB4, ['Ab3', 'C4', 'G4']),
    'Eb':     ('Eb2', 'Eb4', 0x74, ['Eb4', 'G4', 'Bb4']),
    'Bb':     ('Bb1', 'Bb3', 0x74, ['Bb3', 'D4', 'F4']),
    'Bb7':    ('Bb1', 'Bb3', 0xA4, ['Bb3', 'D4', 'Ab4']),
    'Bb/D':   ('D2',  'Bb3', 0x74, ['D4', 'F4', 'Bb4']),
    'Fm':     ('F2',  'F4',  0x73, ['F4', 'Ab4', 'C5']),
    'Fm7':    ('F2',  'F4',  0xA3, ['F4', 'Ab4', 'Eb5']),
    'Fm9':    ('F2',  'F4',  0xE3, ['F4', 'Ab4', 'G5']),
    'G':      ('G1',  'G3',  0x74, ['G3', 'B3', 'D4']),
    'G7':     ('G1',  'G3',  0xA4, ['G3', 'B3', 'F4']),
    'G7sus4': ('G1',  'G3',  0xA5, ['G3', 'C4', 'F4']),
    'Db':     ('Db2', 'Db4', 0x74, ['Db4', 'F4', 'Ab4']),
    'Ddim7':  ('D2',  'D4',  0x63, ['D4', 'F4', 'Ab4']),
    'Dm7b5':  ('D2',  'D4',  0xA3, ['D4', 'F4', 'C5']),
}

class PatternGrid:
    def __init__(self, n_pats=15, rows=128):
        self.n_pats = n_pats
        self.rows = rows
        self.cells = {}

    def set(self, pat, row, ch, note=None, inst=None, vol=None, fx=None, param=None):
        if not (0 <= row < self.rows):
            return
        k = (pat, row, ch)
        c = self.cells.get(k, {})
        if note is not None:
            c['note'] = note_to_midi(note) if isinstance(note, str) else note
        if inst is not None:
            c['instrument'] = inst
        if vol is not None:
            c['volume'] = vol if vol >= 0x10 else (0x10 + vol)
        if fx is not None:
            c['effect'] = fx
            c['effect_param'] = 0 if param is None else param
        elif param is not None:
            c['effect_param'] = param
        self.cells[k] = c

    def off(self, pat, row, ch):
        self.set(pat, row, ch, note='OFF')

def write_drums(g, pat, bar, mode='main', fill=False):
    b = bar * 32
    if mode == 'intro_build':
        for r in range(0, 32, 2):
            if r % 8 == 4 and bar >= 1:
                g.set(pat, b + r, CH_HAT, note='C4', inst=I_HATO, vol=44)
            else:
                v = 52 if (r % 4 == 0) else 34
                g.set(pat, b + r, CH_HAT, note='C4', inst=I_HATC, vol=v)
        if bar == 2:
            for r in (0, 16, 24):
                g.set(pat, b + r, CH_KICK, note='C4', inst=I_KICK, vol=58)
            g.set(pat, b + 8, CH_SNARE, note='C4', inst=I_SNARE, vol=52)
            g.set(pat, b + 24, CH_SNARE, note='C4', inst=I_SNARE, vol=58)
        elif bar == 3:
            for r in (0, 8, 16):
                g.set(pat, b + r, CH_KICK, note='C4', inst=I_KICK, vol=62)
            g.set(pat, b + 8, CH_SNARE, note='C4', inst=I_SNARE, vol=60)
            for r, v in [(16, 50), (18, 44), (20, 52), (22, 48),
                         (24, 58), (26, 54), (28, 60), (29, 46), (30, 64), (31, 52)]:
                g.set(pat, b + r, CH_SNARE, note='C4', inst=I_SNARE, vol=v)
            for r, tn in [(24, 'G4'), (26, 'E4'), (28, 'C4'), (30, 'G3')]:
                g.set(pat, b + r, CH_CRASH, note=tn, inst=I_TOM, vol=56)
        return

    if mode == 'breakdown':
        if bar in (2, 3):
            for r in range(0, 32, 4):
                g.set(pat, b + r, CH_HAT, note='C4', inst=I_HATC, vol=32 if r % 8 == 0 else 22)
        return

    if mode == 'build_up':
        if bar in (0, 1):
            for r in (0, 16):
                g.set(pat, b + r, CH_KICK, note='C4', inst=I_KICK, vol=60)
            for r in range(0, 32, 2):
                v = 44 if r % 4 == 0 else 28
                g.set(pat, b + r, CH_HAT, note='C4', inst=I_HATC, vol=v)
            if bar == 1:
                g.set(pat, b + 24, CH_SNARE, note='C4', inst=I_SNARE, vol=50)
        elif bar == 2:
            for r in (0, 8, 16, 24):
                g.set(pat, b + r, CH_KICK, note='C4', inst=I_KICK, vol=64)
            for r in (8, 24):
                g.set(pat, b + r, CH_SNARE, note='C4', inst=I_SNARE, vol=58)
            for r in range(0, 32, 2):
                if r % 8 == 4:
                    g.set(pat, b + r, CH_HAT, note='C4', inst=I_HATO, vol=44)
                else:
                    g.set(pat, b + r, CH_HAT, note='C4', inst=I_HATC, vol=42)
        else:
            for r in (0, 8, 16):
                g.set(pat, b + r, CH_KICK, note='C4', inst=I_KICK, vol=62)
            roll_rows = [0, 4, 8, 12, 16, 18, 20, 22, 24, 25, 26, 27, 28, 29, 30, 31]
            for idx_r, r in enumerate(roll_rows):
                v = min(64, 34 + idx_r * 2)
                g.set(pat, b + r, CH_SNARE, note='C4', inst=I_SNARE, vol=v)
        return

    if mode == 'solo':
        kick_rows = (0, 6, 12, 16, 22, 28) if bar % 2 == 0 else (0, 6, 12, 16, 24, 30)
    else:
        kick_rows = (0, 8, 16, 24) if bar % 2 == 0 else (0, 8, 14, 16, 24)

    for r in kick_rows:
        g.set(pat, b + r, CH_KICK, note='C4', inst=I_KICK, vol=64 if r % 8 == 0 else 52)

    for r in (8, 24):
        g.set(pat, b + r, CH_SNARE, note='C4', inst=I_SNARE, vol=64)
    if bar % 2 == 1 and not fill:
        g.set(pat, b + 30, CH_SNARE, note='C4', inst=I_SNARE, vol=36)
    if mode in ('chorus', 'solo'):
        g.set(pat, b + 14, CH_SNARE, note='C4', inst=I_SNARE, vol=30)

    for r in range(0, 32, 2):
        if r % 8 == 4:
            g.set(pat, b + r, CH_HAT, note='C4', inst=I_HATO, vol=50)
        else:
            v = 54 if (r % 8 == 0) else (42 if r % 4 == 0 else 30)
            g.set(pat, b + r, CH_HAT, note='C4', inst=I_HATC, vol=v)

    if fill:
        g.set(pat, b + 20, CH_SNARE, note='C4', inst=I_SNARE, vol=48)
        g.set(pat, b + 22, CH_SNARE, note='C4', inst=I_SNARE, vol=42)
        g.set(pat, b + 24, CH_SNARE, note='C4', inst=I_SNARE, vol=64)
        g.set(pat, b + 26, CH_SNARE, note='C4', inst=I_SNARE, vol=52)
        g.set(pat, b + 28, CH_SNARE, note='C4', inst=I_SNARE, vol=60)
        g.set(pat, b + 29, CH_SNARE, note='C4', inst=I_SNARE, vol=46)
        g.set(pat, b + 30, CH_SNARE, note='C4', inst=I_SNARE, vol=64)
        for r, tn in [(24, 'A4'), (26, 'F4'), (28, 'D4'), (30, 'A3')]:
            g.set(pat, b + r, CH_CRASH, note=tn, inst=I_TOM, vol=56)

def write_bass_bar(g, pat, bar, chord_name, next_chord_name=None, style='octave'):
    b = bar * 32
    root_str, _, _, _ = CHORDS[chord_name]
    r_low = note_to_midi(root_str)
    r_hi = r_low + 12
    r_5th = r_low + 7
    next_low = note_to_midi(CHORDS[next_chord_name][0]) if next_chord_name else r_low

    if style == 'sustained_swell':
        g.set(pat, b, CH_BASS, note=r_low, inst=I_BASS, vol=46)
        g.set(pat, b + 16, CH_BASS, note=r_hi, inst=I_BASS, vol=42)
        return

    if style == 'octave':
        pat16 = [
            (r_low, 58), (r_hi, 46), (r_low, 54), (r_hi, 44),
            (r_low, 56), (r_hi, 46), (r_low, 52), (r_hi, 44),
            (r_low, 58), (r_hi, 46), (r_low, 54), (r_hi, 44),
            (r_low, 56), (r_5th, 48), (r_hi, 50), (r_hi, 46)
        ]
        if chord_name.startswith('G') and next_chord_name and next_chord_name.startswith('C'):
            # Dominant leading-tone walk: B1 -> C2!
            pat16[15] = (next_low - 1, 48)
        elif next_low != r_low:
            approach = next_low - 2 if (next_low - r_low) > 2 else next_low + 2
            if approach < note_to_midi('G1'):
                approach += 12
            pat16[15] = (approach, 46)

        for i, (m, v) in enumerate(pat16):
            g.set(pat, b + i * 2, CH_BASS, note=m, inst=I_BASS, vol=v)

    elif style == 'syncopated':
        hits = [
            (0, r_low, 60), (4, r_low, 54), (6, r_hi, 50),
            (8, r_low, 56), (12, r_hi, 48), (14, r_low, 50),
            (16, r_low, 60), (20, r_5th, 52), (22, r_hi, 50),
            (24, r_low, 56), (26, r_hi, 48), (28, r_low, 54), (30, r_hi, 50),
        ]
        for r, m, v in hits:
            g.set(pat, b + r, CH_BASS, note=m, inst=I_BASS, vol=v)

    elif style == 'acid':
        acid_notes = [
            (0, r_low, 60), (2, r_low, 44), (4, r_hi, 56), (6, r_low, 46),
            (8, r_low, 54), (10, r_low+10, 50), (12, r_hi, 58), (14, r_low, 44),
            (16, r_low, 60), (18, r_low, 44), (20, r_5th, 54), (22, r_hi, 52),
            (24, r_low, 56), (26, r_hi, 54), (28, r_low+10, 52), (30, r_hi, 58),
        ]
        for r, m, v in acid_notes:
            g.set(pat, b + r, CH_BASS, note=m, inst=I_ACID, vol=v)

def write_arp_bar(g, pat, bar, chord_name, style='classic_16th'):
    b = bar * 32
    _, arp_root, arp_param, triad = CHORDS[chord_name]
    m_root = note_to_midi(arp_root)
    m_triad = [note_to_midi(x) for x in triad]

    if style == 'classic_16th':
        # Ch 5 (I_ARP25 pan=74 L) & Ch 6 (I_ARP12 pan=182 R)
        for r in range(0, 32, 2):
            if r % 8 == 0:
                g.set(pat, b + r, CH_ARP1, note=m_root, inst=I_ARP25, vol=46, fx=0x00, param=arp_param)
            elif r % 4 == 0:
                g.set(pat, b + r, CH_ARP1, note=m_root, inst=I_ARP25, vol=38, fx=0x00, param=arp_param)
            else:
                g.set(pat, b + r, CH_ARP1, fx=0x00, param=arp_param)
        for r in (4, 12, 20, 28):
            g.set(pat, b + r, CH_ARP2, note=m_root + 12, inst=I_ARP12, vol=36, fx=0x00, param=arp_param)
        for r in (6, 14, 22, 30):
            g.set(pat, b + r, CH_ARP2, fx=0x00, param=arp_param)

    elif style == 'cascade_breakdown':
        # Keep CH_ARP1 on I_ARP25 (pan=74 L) and CH_ARP2 on I_ARP12 (pan=182 R) for lush stereo!
        notes6 = [m_triad[0], m_triad[1], m_triad[2], m_triad[0]+12, m_triad[1]+12, m_triad[2]+12, m_triad[1]+12, m_triad[0]+12]
        for i in range(16):
            n = notes6[i % len(notes6)]
            v = 42 if i % 4 == 0 else 30
            g.set(pat, b + i * 2, CH_ARP1, note=n, inst=I_ARP25, vol=v)
            g.set(pat, b + i * 2 + 1 if (i * 2 + 1 < 32) else b + 31, CH_ARP2, note=n + 12 if i % 4 == 0 else n, inst=I_ARP12, vol=24)

    elif style == 'stabs':
        for r in range(0, 32, 2):
            if r % 8 == 0:
                g.set(pat, b + r, CH_ARP1, note=m_root, inst=I_ARP25, vol=44, fx=0x00, param=arp_param)
            else:
                g.set(pat, b + r, CH_ARP1, fx=0x00, param=arp_param)
        for r in (0, 6, 12, 20, 26):
            g.set(pat, b + r, CH_STAB, note=m_triad[2], inst=I_STAB, vol=46)
            g.set(pat, b + r + 2, CH_STAB, note='OFF')
        for r in (4, 12, 20, 28):
            g.set(pat, b + r, CH_ARP2, note=m_root + 12, inst=I_ARP12, vol=38, fx=0x00, param=arp_param)
            g.set(pat, b + r + 2, CH_ARP2, fx=0x00, param=arp_param)

def write_pad_bar(g, pat, bar, chord_name, vol=34):
    b = bar * 32
    _, _, _, triad = CHORDS[chord_name]
    m0, m1, m2 = [note_to_midi(x) for x in triad]
    g.set(pat, b, CH_PAD1, note=m0, inst=I_PAD, vol=vol, fx=0x08, param=78)
    g.set(pat, b, CH_PAD2, note=m2, inst=I_PAD, vol=vol, fx=0x08, param=178)
    g.set(pat, b + 16, CH_PAD2, note=m1 + 12, inst=I_PAD, vol=max(20, vol - 4), fx=0x08, param=178)

def write_lead_phrase(g, pat, events, ch=CH_LEAD, echo_ch=CH_ECHO1, inst=I_LEAD,
                      base_vol=62, echo_delay=6, echo_ratio=0.45, vib=True, ch_pan=None, echo_pan=206):
    for idx, ev in enumerate(events):
        row, n, dur = ev[0], ev[1], ev[2]
        porta = ev[3] if len(ev) > 3 else 0
        vol = ev[4] if len(ev) > 4 else base_vol
        m = note_to_midi(n)

        if porta > 0:
            g.set(pat, row, ch, note=m, vol=vol, fx=0x03, param=porta)
        elif ch_pan is not None:
            g.set(pat, row, ch, note=m, inst=inst, vol=vol, fx=0x08, param=ch_pan)
        else:
            g.set(pat, row, ch, note=m, inst=inst, vol=vol)

        if vib and dur >= 6:
            vib_start = row + 2
            for vr in range(vib_start, min(128, row + dur)):
                if (pat, vr, ch) not in g.cells:
                    g.set(pat, vr, ch, fx=0x04, param=0x45)

        next_row = events[idx + 1][0] if idx + 1 < len(events) else 999
        if row + dur < next_row and row + dur < 128:
            g.off(pat, row + dur, ch)

        if echo_ch is not None:
            er = row + echo_delay
            if er < 128:
                ev_vol = max(12, int(vol * echo_ratio))
                g.set(pat, er, echo_ch, note=m, inst=inst, vol=ev_vol, fx=0x08, param=echo_pan)
                end_er = min(127, er + min(dur, 6))
                next_er = (events[idx + 1][0] + echo_delay) if idx + 1 < len(events) else 999
                if end_er < next_er and end_er < 128:
                    g.off(pat, end_er, echo_ch)

def build_tune():
    g = PatternGrid(n_pats=15, rows=128)

    PAT_CHORDS = {
        0:  ['Cm', 'Ab', 'Fm7', 'G7'],
        1:  ['Cm', 'Ab', 'Eb', 'Bb'],
        2:  ['Cm', 'Ab', 'Fm7', 'G7'],
        3:  ['Cm', 'Ab', 'Eb', 'Bb'],
        4:  ['Cm', 'Ab', 'Fm7', 'G7'],
        5:  ['Eb', 'Bb/D', 'Cm', 'Ab'],
        6:  ['Eb', 'Bb', 'Ab', 'G7'],
        7:  ['Fm9', 'Cm7', 'Abmaj7', 'G7sus4'],
        8:  ['Fm7', 'Bb7', 'Abmaj7', 'G7'],
        9:  ['Cm', 'Db', 'G7', 'Cm'],
        10: ['Fm', 'Cm', 'Ddim7', 'G7'],
        11: ['Cm', 'Ab', 'Eb', 'Bb'],
        12: ['Cm', 'Ab', 'Fm7', 'G7'],
        13: ['Eb', 'Bb', 'Cm', 'Ab'],
        14: ['Fm7', 'Cm/Eb', 'Dm7b5', 'G7'],
    }

    for p in range(15):
        chords = PAT_CHORDS[p]
        next_pat_first = PAT_CHORDS[1 if p == 14 else (p + 1)][0]

        for bar in range(4):
            c = chords[bar]
            nc = chords[bar + 1] if bar < 3 else next_pat_first

            if p == 0:
                write_drums(g, p, bar, mode='intro_build')
                write_arp_bar(g, p, bar, c, style='classic_16th')
                write_pad_bar(g, p, bar, c, vol=24 + bar * 4)
                if bar >= 1:
                    write_bass_bar(g, p, bar, c, nc, style='sustained_swell' if bar == 1 else 'octave')
                if bar == 2:
                    g.set(p, bar * 32 + 16, CH_FX, note='C4', inst=I_RISER, vol=48, fx=0x08, param=144)
                if bar == 3:
                    g.set(p, bar * 32 + 28, CH_FX, note='C4', inst=I_LASER, vol=44, fx=0x08, param=110)

            elif p in (1, 2, 3, 4):
                fill = (bar == 3 and p in (2, 4))
                write_drums(g, p, bar, mode='main', fill=fill)
                write_bass_bar(g, p, bar, c, nc, style='octave')
                write_arp_bar(g, p, bar, c, style='stabs' if p in (3, 4) else 'classic_16th')
                write_pad_bar(g, p, bar, c, vol=28)
                if bar == 0 and p in (1, 3):
                    g.set(p, 0, CH_CRASH, note='C4', inst=I_CRASH, vol=52)

            elif p in (5, 6):
                write_drums(g, p, bar, mode='chorus', fill=(bar == 3))
                write_bass_bar(g, p, bar, c, nc, style='syncopated')
                write_arp_bar(g, p, bar, c, style='stabs')
                write_pad_bar(g, p, bar, c, vol=36)
                if bar == 0 and p == 5:
                    g.set(p, 0, CH_CRASH, note='C4', inst=I_CRASH, vol=54)

            elif p == 7:
                write_drums(g, p, bar, mode='breakdown')
                write_arp_bar(g, p, bar, c, style='cascade_breakdown')
                write_pad_bar(g, p, bar, c, vol=38)
                if bar == 0:
                    g.set(p, 0, CH_CRASH, note='C4', inst=I_CRASH, vol=46)
                    g.off(p, 0, CH_BASS)
                    g.off(p, 0, CH_STAB)

            elif p == 8:
                write_drums(g, p, bar, mode='build_up')
                write_arp_bar(g, p, bar, c, style='classic_16th')
                write_pad_bar(g, p, bar, c, vol=32)
                if bar in (1, 2):
                    write_bass_bar(g, p, bar, c, nc, style='octave')
                elif bar == 3:
                    for i in range(16):
                        g.set(p, bar * 32 + i * 2, CH_BASS, note='G2' if i < 8 else 'G3', inst=I_BASS, vol=38 + i)
                    g.set(p, bar * 32, CH_FX, note='C4', inst=I_RISER, vol=54, fx=0x08, param=144)
                    g.set(p, bar * 32 + 28, CH_FX, note='D4', inst=I_LASER, vol=46, fx=0x08, param=110)

            elif p in (9, 10):
                write_drums(g, p, bar, mode='solo', fill=(bar == 3))
                write_bass_bar(g, p, bar, c, nc, style='acid')
                write_arp_bar(g, p, bar, c, style='classic_16th')
                if bar == 0 and p == 9:
                    g.set(p, 0, CH_CRASH, note='C4', inst=I_CRASH, vol=54)
                    g.off(p, 0, CH_PAD1)
                    g.off(p, 0, CH_PAD2)

            elif p in (11, 12, 13):
                write_drums(g, p, bar, mode='chorus', fill=(bar == 3 and p in (12, 13)))
                write_bass_bar(g, p, bar, c, nc, style='octave' if p in (11, 12) else 'syncopated')
                write_arp_bar(g, p, bar, c, style='stabs')
                write_pad_bar(g, p, bar, c, vol=34)
                if bar == 0 and p in (11, 13):
                    g.set(p, 0, CH_CRASH, note='C4', inst=I_CRASH, vol=54)

            elif p == 14:
                write_drums(g, p, bar, mode='main', fill=(bar == 3))
                write_bass_bar(g, p, bar, c, nc, style='octave')
                write_arp_bar(g, p, bar, c, style='classic_16th')
                write_pad_bar(g, p, bar, c, vol=32)
                if bar == 3:
                    g.set(p, bar * 32 + 2, CH_FX, note='C4', inst=I_RISER, vol=48, fx=0x08, param=144)
                    g.set(p, bar * 32 + 28, CH_FX, note='C4', inst=I_LASER, vol=42, fx=0x08, param=110)

    # --- Melodies & Counter-Melodies ---

    intro_bell = [
        (0, 'C5', 6), (8, 'G4', 6), (16, 'Eb5', 6), (24, 'D5', 6),
        (32, 'C5', 10), (48, 'Eb5', 6), (56, 'D5', 6),
        (64, 'C5', 6), (72, 'Ab4', 6), (80, 'F4', 6), (88, 'C5', 6),
        (96, 'B4', 12), (112, 'D5', 6), (120, 'G5', 6),
    ]
    write_lead_phrase(g, 0, intro_bell, ch=CH_LEAD, echo_ch=CH_ECHO1, inst=I_BELL, base_vol=52, vib=False, echo_pan=206)

    theme_a1 = [
        (0, 'G4', 6), (8, 'C5', 4), (12, 'D5', 4), (16, 'Eb5', 10), (26, 'D5', 2), (28, 'C5', 2), (30, 'Bb4', 2),
        (32, 'C5', 12), (44, 'Ab4', 4), (48, 'G4', 4), (52, 'Ab4', 4), (56, 'C5', 8),
        (64, 'Bb4', 4), (68, 'Eb5', 4), (72, 'F5', 4), (76, 'G5', 10), (86, 'F5', 2), (88, 'Eb5', 2), (90, 'D5', 2),
        (96, 'F5', 8), (104, 'D5', 4), (108, 'Bb4', 4), (112, 'D5', 6), (120, 'C5', 4), (124, 'Bb4', 4),
    ]
    theme_a2 = [
