        6:  ['Eb', 'Bb', 'Ab', 'G7'],
        7:  ['Fm9', 'Cm7', 'Abmaj7', 'G7sus4'],
        8:  ['Fm7', 'Bb7', 'Abmaj7', 'G7'],
