import os, sys, json, base64, subprocess
sys.path.insert(0, '/tmp/keygen')
from synth_instruments import build_all_instruments

NOTE_NAMES = ['C-', 'C#', 'D-', 'D#', 'E-', 'F-', 'F#', 'G-', 'G#', 'A-', 'A#', 'B-']
NOTE_TO_SEMI = {
    'C': 0, 'C#': 1, 'DB': 1, 'D': 2, 'D#': 3, 'EB': 3, 'E': 4, 'F': 5,
    'F#': 6, 'GB': 6, 'G': 7, 'G#': 8, 'AB': 8, 'A': 9, 'A#': 10, 'BB': 10, 'B': 11
}

def note_to_midi(n):
    if isinstance(n, int):
        return n
    s = n.strip().upper().replace('-', '')
    if s in ('OFF', '==='):
        return 97
    if len(s) >= 2 and s[1] in ('#', 'B'):
        pc = NOTE_TO_SEMI[s[:2]]
        octv = int(s[2:])
    else:
        pc = NOTE_TO_SEMI[s[0]]
        octv = int(s[1:])
    return 1 + octv * 12 + pc

# Instrument IDs (1..17)
I_KICK   = 1
I_SNARE  = 2
I_HATC   = 3   # pan=176 R
I_HATO   = 4   # pan=176 R
I_CRASH  = 5   # pan=78 L
I_TOM    = 6   # pan=78 L
I_BASS   = 7
I_ACID   = 8
I_ARP25  = 9   # pan=44 L
I_ARP12  = 10  # pan=212 R
I_LEAD   = 11  # pan=106 L-mid
I_BELL   = 12  # pan=106 L-mid
I_PAD    = 13
I_STAB   = 14  # pan=192 R
I_LASER  = 15
I_RISER  = 16
I_CNT    = 17  # pan=48 L

# Channels (0..15)
CH_KICK  = 0
CH_SNARE = 1
