# Chord dictionary: (bass_root, arp_root, arp_asc, arp_bounce, triad)
CHORDS = {
    'Cm':     ('C2',  'C4',  0x73, 0x37, ['C4', 'Eb4', 'G4']),
    'Cm7':    ('C2',  'C4',  0xA3, 0x3A, ['C4', 'Eb4', 'Bb4']),
    'Cm/Eb':  ('Eb2', 'C4',  0x73, 0x37, ['Eb4', 'G4', 'C5']),
    'Ab':     ('Ab1', 'Ab3', 0x74, 0x47, ['Ab3', 'C4', 'Eb4']),
    'Abmaj7': ('Ab1', 'Ab3', 0xB4, 0x4B, ['Ab3', 'C4', 'G4']),
    'Eb':     ('Eb2', 'Eb4', 0x74, 0x47, ['Eb4', 'G4', 'Bb4']),
    'Bb':     ('Bb1', 'Bb3', 0x74, 0x47, ['Bb3', 'D4', 'F4']),
    'Bb7':    ('Bb1', 'Bb3', 0xA4, 0x4A, ['Bb3', 'D4', 'Ab4']),
