def note_to_midi(n):
    if isinstance(n, int):
        return n
    s = n.strip().upper().replace('-', '')
    if s in ('OFF', '==='):
        return 97
    if len(s) >= 2 and s[1] in ('#', 'B'):
        pc = NOTE_TO_SEMI[s[:2]]
        octv = int(s[2:])
    else:
        pc = NOTE_TO_SEMI[s[0]]
        octv = int(s[1:])
    return 1 + octv * 12 + pc

